// A RPC devolve um array de linhas reservadas. Dependendo da versão, o node HTTP
// entrega isso como 1 item com array, como array solto, ou já dividido em itens.
// Aqui os três casos viram a mesma coisa: 1 item por linha da fila.
// Fila vazia -> retorna [] e o resto do workflow simplesmente não roda.
const linhas = [];
for (const it of $input.all()) {
  const j = it.json;
  if (Array.isArray(j))            linhas.push(...j);
  else if (Array.isArray(j.data))  linhas.push(...j.data);
  else if (j && j.id && j.recurso) linhas.push(j);
}
return linhas.map((l) => ({ json: l }));

// Monta a chamada da API v2 do Tiny para cada item reservado da fila.
// ATENÇÃO: o token NÃO entra aqui de propósito (P4). Este node monta o corpo
// sem ele; quem prefixa `token=` é a expressão do node HTTP, resolvida só na
// hora do request. Assim o segredo não aparece nem no dado de execução.
const BASE = 'https://api.tiny.com.br/api2/';

const enc = (o) => Object.entries(o)
  .filter(([, v]) => v !== undefined && v !== null && String(v) !== '')
  .map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(String(v)))
  .join('&');

const saida = [];

for (const it of $input.all()) {
  const j = it.json;
  const p = j.params || {};
  const f = { formato: 'JSON' };
  let url;

  switch (j.recurso) {
    case 'pedidos_pesquisa':
      url = BASE + 'pedidos.pesquisa.php';
      f.dataInicial = p.dataInicial; f.dataFinal = p.dataFinal; f.pagina = p.pagina;
      break;
    case 'contatos_pesquisa':
      url = BASE + 'contatos.pesquisa.php';
      f.pagina = p.pagina;
      break;
    case 'nf_pesquisa':
      url = BASE + 'notas.fiscais.pesquisa.php';
      f.dataInicial = p.dataInicial; f.dataFinal = p.dataFinal; f.pagina = p.pagina;
      break;
    case 'cr_pesquisa':
      url = BASE + 'contas.receber.pesquisa.php';
      f.dataInicial = p.dataInicial; f.dataFinal = p.dataFinal; f.pagina = p.pagina;
      break;
    case 'pedido':        url = BASE + 'pedido.obter.php';        f.id = j.chave; break;
    case 'contato':       url = BASE + 'contato.obter.php';       f.id = j.chave; break;
    case 'nota_fiscal':   url = BASE + 'nota.fiscal.obter.php';   f.id = j.chave; break;
    case 'conta_receber': url = BASE + 'conta.receber.obter.php'; f.id = j.chave; break;
    default: continue;
  }

  saida.push({ json: {
    fila_id: j.id, recurso: j.recurso, chave: j.chave,
    params: p, url, corpo: enc(f),
  }});
}

return saida;

// Traduz a resposta do Tiny numa única chamada de RPC no Supabase.
// Busca   -> fn_backfill_aplicar com a lista do que enfileirar (+ próxima página)
// Detalhe -> fn_backfill_aplicar com o objeto cru
// Falha   -> fn_backfill_falha (volta pra fila até 4 tentativas)
// NÃO renomear o node 'Montar requisicao Tiny' — a referência abaixo é pelo nome.

const PRIO = { pedidos_pesquisa: 1, pedido: 2, contatos_pesquisa: 3, contato: 4,
               nf_pesquisa: 5, nota_fiscal: 6, cr_pesquisa: 7, conta_receber: 8 };
const DETALHE = { pedidos_pesquisa: 'pedido', contatos_pesquisa: 'contato',
                  nf_pesquisa: 'nota_fiscal', cr_pesquisa: 'conta_receber' };
const META = new Set(['status', 'status_processamento', 'codigo_erro', 'erros',
                      'pagina', 'numero_paginas', 'registros']);

const reqs  = $('Montar requisicao Tiny').all();
const itens = $input.all();
const saida = [];

const falhar = (fila_id, msg, terminal) => saida.push({ json: {
  rpc: 'fn_backfill_falha',
  body: { p_fila_id: fila_id, p_erro: String(msg).slice(0, 480),
          p_terminal: !!terminal },
}});

for (let i = 0; i < itens.length; i++) {
  const req  = (reqs[i] || {}).json || {};
  const resp = itens[i].json || {};
  const ret  = resp.retorno || (resp.body && resp.body.retorno) || null;

  if (!ret) {
    falhar(req.fila_id, 'sem envelope retorno: ' + JSON.stringify(resp).slice(0, 300));
    continue;
  }

  const cod = String(ret.codigo_erro == null ? '' : ret.codigo_erro);

  // Na v2 o HTTP é 200 mesmo em erro — o IF de verdade é este (modelo mental 8).
  if (String(ret.status || '').toUpperCase() !== 'OK') {
    // 20 = consulta sem registros. Não é erro: a janela simplesmente está vazia.
    if (cod === '20' && String(req.recurso).endsWith('_pesquisa')) {
      saida.push({ json: { rpc: 'fn_backfill_aplicar',
        body: { p_fila_id: req.fila_id, p_recurso: req.recurso, p_payload: [] } } });
      continue;
    }
    // 32 = registro não localizado. Não adianta repetir: encerra a linha.
    const erros = (ret.erros || []).map((e) => (e && e.erro) || e).join(' | ');
    falhar(req.fila_id, 'codigo ' + cod + ': ' + (erros || ret.status), cod === '32');
    continue;
  }

  // ---------- resultado de busca ----------
  if (String(req.recurso).endsWith('_pesquisa')) {
    const chaveLista = Object.keys(ret).find((k) => Array.isArray(ret[k]));
    const brutos = chaveLista ? ret[chaveLista] : [];
    // o Tiny embrulha cada registro: [{pedido:{...}}, ...] -> desembrulha
    const registros = brutos.map((x) => (x && typeof x === 'object' && !Array.isArray(x))
      ? (x[Object.keys(x)[0]] && typeof x[Object.keys(x)[0]] === 'object'
          ? x[Object.keys(x)[0]] : x)
      : x);

    const alvo = DETALHE[req.recurso];
    const novos = registros
      .map((r) => ({
        recurso: alvo,
        chave: String((r && r.id) == null ? '' : r.id),
        referencia: String((r && (r.numero || r.numero_documento || r.nome)) || ''),
        prioridade: PRIO[alvo],
      }))
      .filter((r) => r.chave && r.chave !== 'undefined' && r.chave !== 'null');

    const pag   = Number(ret.pagina || (req.params && req.params.pagina) || 1);
    const total = Number(ret.numero_paginas || 1);
    if (pag < total) {
      const prox = Object.assign({}, req.params || {}, { pagina: pag + 1 });
      const rotulo = (req.params && req.params.janela)
        ? req.params.janela + ':p' + (pag + 1)
        : 'p' + (pag + 1);
      novos.push({ recurso: req.recurso, chave: rotulo,
                   prioridade: PRIO[req.recurso], params: prox });
    }

    saida.push({ json: { rpc: 'fn_backfill_aplicar',
      body: { p_fila_id: req.fila_id, p_recurso: req.recurso, p_payload: novos } } });
    continue;
  }

  // ---------- detalhe ----------
  const chaveObj = Object.keys(ret).find(
    (k) => !META.has(k) && ret[k] && typeof ret[k] === 'object');
  const payload = chaveObj ? ret[chaveObj] : null;
  if (!payload) { falhar(req.fila_id, 'retorno OK sem objeto de detalhe'); continue; }

  saida.push({ json: { rpc: 'fn_backfill_aplicar',
    body: { p_fila_id: req.fila_id, p_recurso: req.recurso, p_payload: payload } } });
}

return saida;
